def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []
    for word in words:
        if word.isalpha():
            ordered_word = ''.join(sorted(word))
            ordered_words.append(ordered_word)
        else:
            ordered_word = ''.join(sorted(c for c in word if c.isalpha()))
            non_alpha_chars = [c for c in word if not c.isalpha()]
            ordered_word_list = list(ordered_word)
            for c in non_alpha_chars:
                ordered_word_list.insert(word.index(c), c)
            ordered_word = ''.join(ordered_word_list)
            ordered_words.append(ordered_word)
    return ' '.join(ordered_words)

