def tri(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return [1]
    if n == 1:
        return [1, 3]

    sequence = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            sequence.append(1 + i / 2)
        else:
            sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i])

    return sequence

