def simplify(x, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    x_num, x_den = map(int, x.split('/'))
    n_num, n_den = map(int, n.split('/'))

    prod_num = x_num * n_num
    prod_den = x_den * n_den

    g = gcd(prod_num, prod_den)
    simplified_num = prod_num // g
    simplified_den = prod_den // g

    return simplified_den == 1

